INSERT INTO ai.messages ("id", "conversation_id", "role", "content", "meta", "created_at") VALUES ('e244131f-e82c-4bbd-a25e-0533c3301125', (SELECT id FROM ai.conversations WHERE user_id = '8f703deb-30a0-4082-aa73-bb671a6b5e81' AND thread_id = '4fd549c5-54ed-4b02-a205-535890f2e79c'), 'assistant', 'Satmak istediğiniz **ASELS** hissesi 100 adet olarak girildi, ancak hesabınızda yalnızca **4 adet** mevcut. Bu yüzden işlem önerisi **reddedildi**.

**Engelleyici neden:** Satılabilir miktar yetersiz – ASELS için 4 adet mevcut, 100 adet talep edildi.

**Açıklamalar**
- Bu bir işlem önerisidir; onaylanana kadar hiçbir emir iletilmemiştir.
